const atlas=typeof Image==='undefined'?{}:new Image();atlas.src='art/activities.png';
export const illustratedActivities=['garden','pig','chicken','tarot','live','tea','bake','paint','sew','recycle','incense','fish','chant','beads','meditate','sweep','meal','prostrate','sermon'];
export function drawIllustratedActivity(view){if(!atlas.complete||!atlas.naturalWidth)return false;const index=illustratedActivities.indexOf(view.id);if(index<0)return false;const c=view.ctx,r=view.canvas.getBoundingClientRect(),s=view.scene,t=s.time,age=t-view.lastHit,hit=Math.max(0,1-age/.65);view.scale=Math.min(r.width/700,r.height/950);view.ox=r.width/2-450*view.scale;view.oy=r.height/2-475*view.scale;const bg=c.createLinearGradient(0,0,0,r.height);bg.addColorStop(0,'#fff4d5');bg.addColorStop(1,'#c7d8ad');c.fillStyle=bg;c.fillRect(0,0,r.width,r.height);c.save();c.translate(view.ox,view.oy);c.scale(view.scale,view.scale);const cw=atlas.naturalWidth/5,ch=atlas.naturalHeight/4;s.rounded(116,215,668,480,30,'#fff7df','#d4b77c');c.save();c.beginPath();c.roundRect(130,230,640,450,22);c.clip();c.drawImage(atlas,(index%5)*cw+3,Math.floor(index/5)*ch+3,cw-6,ch-6,130-hit*3,230-hit*3,640+hit*6,450+hit*6);c.restore();s.text('✦ Mỗi thao tác là một điều nhỏ tốt lành ✦',450,175,22,'#536f45');s.character({...view.player,x:450,y:860,name:'',preview:true,action:view.id,animationStarted:Date.now()-age*1000},false);const symbols={garden:'💧',pig:'🥬',chicken:'🌾',tarot:'🃏',live:'♥',tea:'☁',bake:'🥮',paint:'🖌',sew:'🧵',recycle:'♻',incense:'☁',fish:'🐟',chant:'♪',beads:'●',meditate:'◯',sweep:'🍂',meal:'🥢',prostrate:'✦',sermon:'🪷'};
const gentle=matchMedia('(prefers-reduced-motion: reduce)').matches;
if(!gentle){const a=view.id,beat=hit||(.12+.08*Math.sin(t*2)),swing=Math.sin(t*3)*.15;
c.save();c.translate(535,390);c.rotate((a==='sweep'?-0.5:a==='paint'?-.3:0)+swing+hit*.45);
if(['chant','bake','paint','sew','sweep','fish','meal'].includes(a)){const tool=a==='fish'?'net':a; s.line(0,-65,0,90,'#87603c',a==='sew'?3:9);if(tool==='chant'||tool==='bake')s.ellipse(0,90,18,13,'#d4ae72');if(tool==='paint'){s.path([[-9,65],[9,65],[5,105],[-5,105]],'#5e9b77');}if(tool==='sew'){s.line(0,75,20,130,'#d8b3cb',2);}if(tool==='sweep'){s.path([[-10,65],[10,65],[39,130],[-39,130]],'#d9b46a');for(let i=-3;i<=3;i++)s.line(i*3,80,i*10,125,'#b78d4e',2);}if(tool==='net'){s.ellipse(0,105,55,40,'#ffffff20','#b89a62');for(let i=-3;i<=3;i++)s.line(i*12,75,i*12,133,'#e2d5ac88',1);}if(tool==='meal')s.line(15,-65,15,90,'#87603c',5);}
c.restore();
if(['garden','tea','pig','chicken'].includes(a)&&hit>0){for(let i=0;i<12;i++){const xx=360+i*16+Math.sin(i)*hit*35,yy=320+age*230+i%3*13;s.ellipse(xx,yy,a==='garden'||a==='tea'?3:5,a==='garden'||a==='tea'?7:3,a==='garden'?'#6bb8cb':a==='tea'?'#b9b876':'#d9b061');}}
if(a==='beads'){c.save();c.translate(450,470);c.rotate(t*.1+view.scene.task.rotation);for(let i=0;i<18;i++){const angle=i*Math.PI/9;s.ellipse(Math.cos(angle)*145,Math.sin(angle)*110,9,9,'#a87948','#dbba7c');}c.restore();}
if(['meditate','sermon','prostrate'].includes(a)){c.save();c.globalAlpha=.2+beat*.15;c.beginPath();c.ellipse(450,480,130+Math.sin(t)*25,95+Math.sin(t)*18,0,0,Math.PI*2);c.strokeStyle='#f8e3a0';c.lineWidth=5;c.stroke();c.restore();}
for(let i=0;i<7;i++){const pulse=hit>0?age:((t*.2+i*.14)%1);let x=210+i*75,y=500;if(['garden','chicken','pig'].includes(a))y=280+pulse*270;else if(['tea','incense','live','chant'].includes(a))y=610-pulse*280;else if(a==='fish'){x=450+Math.sin(t*1.8+i)*180;y=470+Math.cos(t+i)*90;}else if(a==='beads'||a==='meditate'){x=450+Math.cos(t+i)*170;y=460+Math.sin(t+i)*120;}else if(a==='sweep'||a==='paint'||a==='sew'){x=240+((t*.5+i*.15)%1)*420;y=380+i*25;}else y=440+Math.sin(t*2+i)*45;c.save();c.globalAlpha=hit>0?.9:.28;s.text(symbols[a]||'✦',x,y,24+hit*12,'#58845a');c.restore();}}
if(hit>0){s.text('+1 XP',650,755-age*40,35,'#49794c');for(let i=0;i<5;i++)s.text('✦',240+i*100,690-age*70,18,'#bf914d');}c.restore();return true;}
export function drawActivityMarker(scene,id,x,y){const i=illustratedActivities.indexOf(id);if(i<0||!atlas.complete||!atlas.naturalWidth)return;const cw=atlas.naturalWidth/5,ch=atlas.naturalHeight/4;scene.rounded(x-40,y-51,80,60,10,'#fff3d6','#b99b65');const c=scene.ctx;c.save();c.beginPath();c.roundRect(x-37,y-48,74,54,8);c.clip();c.drawImage(atlas,i%5*cw+3,Math.floor(i/5)*ch+3,cw-6,ch-6,x-37,y-48,74,54);c.restore();}
